import {type PropsWithChildren, createContext, useContext, useMemo} from 'react'
import {type SettingContextType, useSetting} from '@github-ui/ruleset-settings-state/use-setting'
import type {CopilotModelValue} from '../types'
import type {MultiSelectConditionExpression} from '@github-ui/ruleset-settings-state/types'

type CopilotModelAllowedTypes = 'add'

type ContextType = SettingContextType<CopilotModelValue, CopilotModelAllowedTypes, MultiSelectConditionExpression>
export const SettingContext = createContext<ContextType | undefined>(undefined)

export function SettingProvider({children}: PropsWithChildren) {
  const reducerValue = useSetting<CopilotModelValue, CopilotModelAllowedTypes, MultiSelectConditionExpression>()
  const value = useMemo(() => reducerValue, [reducerValue])
  return <SettingContext.Provider value={value}>{children}</SettingContext.Provider>
}

export function useSettingContext(): ContextType {
  const context = useContext(SettingContext)
  if (!context) {
    throw new Error('useSettingContext must be used within a SettingProvider')
  }
  return context
}

try{ SettingContext.displayName ||= 'SettingContext' } catch {}
try{ SettingProvider.displayName ||= 'SettingProvider' } catch {}