import {Breadcrumbs, PageHeader, Stack} from '@primer/react'
import type {PropsWithChildren} from 'react'
import {useSearchParams} from '@github-ui/use-navigate'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {usePartialRouter} from '../contexts/PartialRouteContext'
import {useConfirmableNavigate} from '../hooks/use-confirmable-navigate'
import {Page} from '../types'
import {Banner} from './Banner'

export function Layout({children}: PropsWithChildren) {
  const {page} = usePartialRouter()
  const navigate = useConfirmableNavigate()
  const title = page === Page.Overview ? 'Copilot models' : page === Page.UpdateRule ? 'Update rule' : 'New rule'
  const [searchParams] = useSearchParams()
  const isAiControlsEnabled = isFeatureEnabled('enterprise_ai_controls')
  const showTitle = searchParams.has('tab')

  return (
    <Stack gap="spacious">
      <Banner />
      {!isAiControlsEnabled && (
        <PageHeader data-hpc hasBorder={showTitle}>
          <PageHeader.ContextArea hidden={page === Page.Overview}>
            <Breadcrumbs>
              <Breadcrumbs.Item tabIndex={0} className="cursor-pointer" onClick={() => navigate(Page.Overview)}>
                Copilot models
              </Breadcrumbs.Item>
              <Breadcrumbs.Item selected>{title}</Breadcrumbs.Item>
            </Breadcrumbs>
          </PageHeader.ContextArea>
          {showTitle && (
            <PageHeader.TitleArea>
              <PageHeader.Title as="h1">{title}</PageHeader.Title>
            </PageHeader.TitleArea>
          )}
        </PageHeader>
      )}
      {children}
    </Stack>
  )
}

try{ Layout.displayName ||= 'Layout' } catch {}