import {useCallback} from 'react'
import {usePartialRouter} from '../contexts/PartialRouteContext'
import {useDirtyValueContext} from '../contexts/DirtySettingContext'
import {Page} from '../types'

export function useConfirmableNavigate() {
  const [isValueDirty] = useDirtyValueContext()
  const {navigate} = usePartialRouter()

  return useCallback(
    (page: Page, ruleId?: number) => {
      if (!isValueDirty || window.confirm('You have unsaved changes. Are you sure you want to leave this page?')) {
        navigate(page, ruleId)
      }
    },
    [isValueDirty, navigate],
  )
}
