import {useMemo} from 'react'
import type {Model} from '../../types'
import {publisherMap} from '../PublisherIcon'
import {InlineSummary, type SummaryItem} from './InlineSummary'

export function InlineModelSummary({selectedModels, className}: {selectedModels: Model[]; className?: string}) {
  const items = useMemo<SummaryItem[]>(
    () =>
      selectedModels.map(model => ({
        key: model.name,
        displayName: model.displayName,
        size: 16,
        square: true,
        ...(publisherMap[model.publisher] ?? {}),
      })),
    [selectedModels],
  )

  return (
    <InlineSummary
      items={items}
      title={items.length === 1 ? 'model' : 'models'}
      shape="square"
      className={className}
      showFirstItem
    />
  )
}

try{ InlineModelSummary.displayName ||= 'InlineModelSummary' } catch {}