import {OverviewPage} from './routes/OverviewPage'
import {RulePage} from './routes/RulePage'
import {Layout} from './components/Layout'
import {SettingProvider} from './contexts/SettingContext'
import {type EnabledFeatures, Page, type Paths} from './types'
import {PathsProvider} from './contexts/PathsContext'
import {PartialRouterProvider, usePartialRouter} from './contexts/PartialRouteContext'
import {BannerProvider, useBannerContext} from './contexts/BannerContext'
import {EnabledFeaturesProvider} from './contexts/EnabledFeaturesContext'
import {PermissionsProvider} from './contexts/PermissionsContext'
import {DirtyValueProvider} from './contexts/DirtySettingContext'
import {useEffect} from 'react'

export type CopilotModelSettingsProps = {
  paths: Paths
  enabledFeatures?: EnabledFeatures
  canWrite?: boolean
}

export function CopilotModelSettings({paths, enabledFeatures, canWrite = true}: CopilotModelSettingsProps) {
  return (
    <PermissionsProvider canWrite={canWrite}>
      <EnabledFeaturesProvider enabledFeatures={enabledFeatures}>
        <PartialRouterProvider>
          <PathsProvider paths={paths}>
            <BannerProvider>
              <DirtyValueProvider>
                <SettingProvider>
                  <CopilotModelSettingsInner />
                </SettingProvider>
              </DirtyValueProvider>
            </BannerProvider>
          </PathsProvider>
        </PartialRouterProvider>
      </EnabledFeaturesProvider>
    </PermissionsProvider>
  )
}

function CopilotModelSettingsInner() {
  const {page} = usePartialRouter()
  const {clearBanner} = useBannerContext()

  useEffect(() => {
    clearBanner()
  }, [page, clearBanner])
  return (
    <Layout>
      <Route page={page} />
    </Layout>
  )
}

function Route({page}: {page: Page}) {
  switch (page) {
    case Page.Overview:
      return <OverviewPage />
    case Page.CreateRule:
    case Page.UpdateRule:
      return <RulePage />
    default:
      return <OverviewPage />
  }
}

try{ CopilotModelSettings.displayName ||= 'CopilotModelSettings' } catch {}
try{ CopilotModelSettingsInner.displayName ||= 'CopilotModelSettingsInner' } catch {}
try{ Route.displayName ||= 'Route' } catch {}