import {useCallback, useMemo, useState} from 'react'
import {SelectPanel, Button} from '@primer/react'
import type {ActionListGroupedListProps} from '@primer/react/deprecated'
import {AiModelIcon, TriangleDownIcon} from '@primer/octicons-react'
import {Category, ModelValue, type AugmentedActionListItemInput, type Model} from '../types'
import {modelToActionListItem} from '../utils/model-to-action-list-item'

const groupMetadata: ActionListGroupedListProps['groupMetadata'] = [
  {groupId: Category.Fast, header: {title: 'Fast and cost-efficient', variant: 'filled'}},
  {groupId: Category.Versatile, header: {title: 'Versatile and highly intelligent', variant: 'filled'}},
  {groupId: Category.Powerful, header: {title: 'Most powerful at complex tasks', variant: 'filled'}},
]

type ModelSelectorProps = {
  isSyncing: boolean
  models: Model[]
  selectedModels: Model[]
  setModel(key: string, value: ModelValue): void
  disabled?: boolean
}

export const ModelSelector = ({isSyncing, models, selectedModels, setModel, disabled = false}: ModelSelectorProps) => {
  const [filter, setFilter] = useState('')
  const togglePolicy = useCallback(
    (newSelectedModels?: AugmentedActionListItemInput[]) => {
      if (!newSelectedModels) {
        if (selectedModels[0]) setModel(selectedModels[0].name, ModelValue.Disabled)
      } else if (newSelectedModels.length > selectedModels.length) {
        const newModel = newSelectedModels.find(({id}) => !selectedModels.map(m => m.name).includes(id as string))
        if (newModel) {
          setModel(newModel.id as string, ModelValue.Enabled)
        }
      } else {
        const newModel = selectedModels.find(({name}) => !newSelectedModels.map(m => m.id).includes(name))
        if (newModel) {
          setModel(newModel.name, ModelValue.Disabled)
        }
      }
    },
    [selectedModels, setModel],
  )

  const filteredItems = useMemo(
    () =>
      models
        .filter(
          item =>
            // design guidelines say to always show selected item in the list
            selectedModels.some(selectedItem => selectedItem.name === item.name) ||
            // then filter the rest
            item.displayName.toLowerCase().includes(filter.toLowerCase()),
        )
        .map(item => modelToActionListItem(item)),
    [filter, models, selectedModels],
  )
  const itemInputModels = useMemo(() => selectedModels.map(model => modelToActionListItem(model)), [selectedModels])
  const showGroups = useMemo(() => models.every(model => !!model.category), [models])
  const [open, setOpen] = useState(false)

  return (
    <SelectPanel
      loading={isSyncing}
      groupMetadata={showGroups ? groupMetadata : undefined}
      renderAnchor={({children, ...anchorProps}) => (
        <Button
          {...anchorProps}
          trailingAction={TriangleDownIcon}
          aria-haspopup="dialog"
          leadingVisual={AiModelIcon}
          disabled={disabled}
        >
          Add models
        </Button>
      )}
      title="Select models"
      placeholderText="Filter models"
      open={open}
      onOpenChange={setOpen}
      items={filteredItems}
      selected={itemInputModels}
      //@ts-expect-error TODO types not being inferred based on items/selected props
      onSelectedChange={togglePolicy}
      onFilterChange={setFilter}
      overlayProps={{
        width: 'medium',
        height: 'medium',
      }}
    />
  )
}

try{ ModelSelector.displayName ||= 'ModelSelector' } catch {}