import type {AugmentedActionListItemInput, Model} from '../types'
import {PublisherIcon} from '../components/PublisherIcon'

export function modelToActionListItem(model: Model): AugmentedActionListItemInput {
  return {
    groupId: model.category,
    leadingVisual: () => PublisherIcon({publisher: model.publisher}),
    text: model.displayName,
    id: model.name,
    value: model.value,
  }
}
