import type {PropsWithChildren} from 'react'
import {clsx} from 'clsx'
import {useSlots} from '@primer/react/experimental'
import {Blankslate} from './components/Blankslate'
import {Row} from './components/Row'
import {SkeletonRow as DefaultSkeletonRow} from './components/SkeletonRow'
import {Header} from './components/Header'
import {BoxHeader} from './components/BoxHeader'
import styles from './PanelList.module.css'

PanelList.BoxHeaderActions = BoxHeaderActions
PanelList.HeaderActions = HeaderActions
PanelList.Blankslate = Blankslate
PanelList.Row = Row
PanelList.Rows = Rows
PanelList.SkeletonRow = SkeletonRow

export {PanelList}

const panelSlotConfig = {
  boxHeaderActions: PanelList.BoxHeaderActions,
  headerActions: PanelList.HeaderActions,
  blankslate: PanelList.Blankslate,
  rows: PanelList.Rows,
  skeletonRow: PanelList.SkeletonRow,
}

export type PanelListProps = {
  title?: string
  subtitle?: string
  boxTitle?: string
  isLoading?: boolean
  isEmpty?: boolean
  condensed?: boolean
}

function PanelList({
  children: slottedChildren,
  boxTitle,
  title,
  subtitle,
  isLoading,
  isEmpty,
  condensed = false,
}: PropsWithChildren<PanelListProps>) {
  const [{boxHeaderActions, headerActions, blankslate, rows, skeletonRow}, children] = useSlots(
    slottedChildren,
    panelSlotConfig,
  )
  let content = null
  if (isLoading && isEmpty) {
    content = (
      <ul data-testid="PanelList.SkeletonRows" aria-busy="true">
        {skeletonRow ?? <DefaultSkeletonRow />}
        {skeletonRow ?? <DefaultSkeletonRow />}
      </ul>
    )
  } else if (isEmpty) {
    // Render a default blankslate if none is given
    content = blankslate ?? <Blankslate heading="No data" />
  } else {
    content = rows
  }
  return (
    <div className={clsx(styles.PanelList, 'd-flex flex-column gap-3', condensed && styles.Condensed)}>
      {title && (
        <Header title={title} subtitle={subtitle}>
          {headerActions}
        </Header>
      )}
      <div className="Box">
        {boxTitle ? (
          <BoxHeader title={boxTitle} isSyncing={isLoading}>
            {boxHeaderActions}
          </BoxHeader>
        ) : null}
        {content}
        {children}
      </div>
    </div>
  )
}

function BoxHeaderActions({children}: PropsWithChildren) {
  return children
}
BoxHeaderActions.displayName = 'PanelList.BoxHeaderActions'

function HeaderActions({children}: PropsWithChildren) {
  return children
}
HeaderActions.displayName = 'PanelList.HeaderActions'

function Rows({children}: PropsWithChildren) {
  return <ul>{children}</ul>
}
Rows.displayName = 'PanelList.Rows'

function SkeletonRow({children}: PropsWithChildren) {
  return children
}
SkeletonRow.displayName = 'PanelList.SkeletonRow'

try{ PanelList.displayName ||= 'PanelList' } catch {}