import {IconButton} from '@primer/react'
import {XIcon, OrganizationIcon} from '@primer/octicons-react'
import {OrgSelector, simpleOrgLoader, type BaseOrganization} from '@github-ui/org-selector'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {PanelList} from '@github-ui/panel-list'
import {useOrganizations} from '../../hooks/use-organizations'

interface OrgsPanelProps {
  selectedOrgs: BaseOrganization[]
  setSelectedOrgs: (selected: BaseOrganization[]) => void
}

export function OrgsPanel({selectedOrgs, setSelectedOrgs}: OrgsPanelProps) {
  const {organizations, isSyncing} = useOrganizations()

  return (
    <PanelList boxTitle="Target organizations" isEmpty={selectedOrgs.length === 0} isLoading={isSyncing}>
      <PanelList.BoxHeaderActions>
        <OrgSelector
          buttonText="Add organizations"
          selection={selectedOrgs}
          orgLoader={simpleOrgLoader(organizations)}
          selectionVariant="multiple"
          selectOrg={selectedOrg => {
            setSelectedOrgs([...selectedOrgs, selectedOrg])
          }}
          removeOrg={removedOrg => setSelectedOrgs(selectedOrgs.filter(org => org.name !== removedOrg.name))}
        />
      </PanelList.BoxHeaderActions>
      <PanelList.Rows>
        {selectedOrgs.map(org => (
          <PanelList.Row key={org.name}>
            {org.primaryAvatarUrl && (
              <PanelList.Row.LeadingVisual>
                <GitHubAvatar size={16} square src={org.primaryAvatarUrl} />
              </PanelList.Row.LeadingVisual>
            )}
            {org.name}
            <PanelList.Row.Actions>
              <IconButton
                icon={XIcon}
                aria-label={`Remove ${org.name} organization`}
                variant="invisible"
                onClick={() => {
                  setSelectedOrgs(selectedOrgs.filter(selectedItem => selectedItem.name !== org.name))
                }}
              />
            </PanelList.Row.Actions>
          </PanelList.Row>
        ))}
      </PanelList.Rows>
      <PanelList.Blankslate heading="No organizations have been added yet" icon={OrganizationIcon} />
    </PanelList>
  )
}

try{ OrgsPanel.displayName ||= 'OrgsPanel' } catch {}