import type {PropsWithChildren} from 'react'
import {clsx} from 'clsx'
import {Spinner} from '@primer/react'
import {Stack} from '@primer/react/experimental'
import styles from './BoxHeader.module.css'

export function BoxHeader({
  children,
  title,
  isSyncing = false,
}: PropsWithChildren<{title: string; isSyncing?: boolean}>) {
  return (
    <Stack
      direction="horizontal"
      justify="space-between"
      align="center"
      className={clsx(styles.BoxHeader, 'Box-header py-2')}
    >
      <span className="Box-title text-bold d-flex flex-items-center">
        {title}
        {isSyncing ? <Spinner srText={`Loading ${title}`} className="ml-2" size="small" /> : null}
      </span>
      {children}
    </Stack>
  )
}

try{ BoxHeader.displayName ||= 'BoxHeader' } catch {}