import {type PropsWithChildren, createContext, useContext, useMemo, useState} from 'react'
import {Page, type PartialRouter} from '../types'

export const PartialRouterContext = createContext<PartialRouter>({
  page: Page.Overview,
  ruleId: undefined,
  navigate() {},
})

export function PartialRouterProvider({children}: PropsWithChildren) {
  const [page, setPage] = useState<Page>(Page.Overview)
  const [ruleId, setRuleId] = useState<number | undefined>(undefined)
  const value = useMemo(
    () => ({
      page,
      ruleId,
      navigate: (newPage: Page, newRuleId?: number) => {
        setPage(newPage)
        setRuleId(newRuleId)
      },
    }),
    [page, ruleId, setPage, setRuleId],
  )
  return <PartialRouterContext.Provider value={value}>{children}</PartialRouterContext.Provider>
}

export function usePartialRouter(): PartialRouter {
  const context = useContext(PartialRouterContext)
  if (!context) {
    throw new Error('usePartialRouter must be used within a PartialRouterProvider')
  }
  return context
}

try{ PartialRouterContext.displayName ||= 'PartialRouterContext' } catch {}
try{ PartialRouterProvider.displayName ||= 'PartialRouterProvider' } catch {}