import {type Dispatch, type PropsWithChildren, type SetStateAction, createContext, useContext, useState} from 'react'

type DirtyValue = [boolean, Dispatch<SetStateAction<boolean>>]

export const DirtyValueContext = createContext<DirtyValue | undefined>(undefined)

export function DirtyValueProvider({children}: PropsWithChildren) {
  // eslint-disable-next-line @eslint-react/naming-convention/use-state
  const state = useState<boolean>(false)
  return <DirtyValueContext.Provider value={state}>{children}</DirtyValueContext.Provider>
}

export function useDirtyValueContext(): DirtyValue {
  const context = useContext(DirtyValueContext)
  if (!context) {
    throw new Error('useDirtyValueContext must be used within a DirtyValueProvider')
  }
  return context
}

try{ DirtyValueContext.displayName ||= 'DirtyValueContext' } catch {}
try{ DirtyValueProvider.displayName ||= 'DirtyValueProvider' } catch {}