import {type PropsWithChildren, createContext, useContext, useMemo} from 'react'

export type Permissions = {
  canWrite: boolean
}

export const PermissionsContext = createContext<Permissions | undefined>(undefined)

export function PermissionsProvider({children, canWrite = true}: PropsWithChildren<{canWrite?: boolean}>) {
  const value = useMemo(() => ({canWrite}), [canWrite])
  return <PermissionsContext.Provider value={value}>{children}</PermissionsContext.Provider>
}

export function usePermissions(): Permissions {
  const context = useContext(PermissionsContext)
  if (!context) {
    throw new Error('usePermissions must be used within a PermissionsProvider')
  }
  return context
}

try{ PermissionsContext.displayName ||= 'PermissionsContext' } catch {}
try{ PermissionsProvider.displayName ||= 'PermissionsProvider' } catch {}