import {useMemo} from 'react'
import {InlineSummary, type SummaryItem} from './InlineSummary'
import type {BaseOrganization} from '@github-ui/org-selector'

export function InlineOrganizationSummary({
  organizations,
  className,
}: {
  organizations: BaseOrganization[]
  className?: string
}) {
  const items = useMemo<SummaryItem[]>(
    () =>
      organizations.map(org => ({
        key: org.name,
        displayName: org.name,
        size: 16,
        src: org.primaryAvatarUrl ?? '',
      })),
    [organizations],
  )

  return (
    <InlineSummary
      shape="square"
      items={items}
      title={items.length === 1 ? 'Organization' : 'Organizations'}
      className={className}
    />
  )
}

try{ InlineOrganizationSummary.displayName ||= 'InlineOrganizationSummary' } catch {}