import {type PropsWithChildren, createContext, useContext, useMemo} from 'react'
import type {EnabledFeatures} from '../types'

export const EnabledFeaturesContext = createContext<EnabledFeatures | undefined>(undefined)

export function EnabledFeaturesProvider({
  children,
  enabledFeatures,
}: PropsWithChildren<{enabledFeatures?: EnabledFeatures}>) {
  const value = useMemo(() => enabledFeatures ?? {}, [enabledFeatures])
  return <EnabledFeaturesContext.Provider value={value}>{children}</EnabledFeaturesContext.Provider>
}

export function useEnabledFeatures(): EnabledFeatures {
  const context = useContext(EnabledFeaturesContext)
  if (!context) {
    throw new Error('useEnabledFeatures must be used within a EnabledFeaturesProvider')
  }
  return context
}

try{ EnabledFeaturesContext.displayName ||= 'EnabledFeaturesContext' } catch {}
try{ EnabledFeaturesProvider.displayName ||= 'EnabledFeaturesProvider' } catch {}