import {useCallback, useMemo, useState} from 'react'
import {useQuery} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import type {CopilotModelSetting} from '../types'
import {usePathsContext} from '../contexts/PathsContext'
import {useBannerContext} from '../contexts/BannerContext'
import {useSettingContext} from '../contexts/SettingContext'
import {useDirtyValueContext} from '../contexts/DirtySettingContext'

export function useSettings() {
  const {settingsPath} = usePathsContext()
  const {clearBanner, setBanner} = useBannerContext()
  const settingContext = useSettingContext()
  const [_, setIsValueDirty] = useDirtyValueContext()
  const [isUpdating, setIsUpdating] = useState(false)

  const wrappedSetValue = useCallback(
    (value: CopilotModelSetting['value']) => {
      setIsValueDirty(true)
      settingContext.setValue(value)
    },
    [settingContext, setIsValueDirty],
  )

  const wrappedInitialize = useCallback(
    (setting: CopilotModelSetting) => {
      setIsValueDirty(false)
      settingContext.initialize(setting)
    },
    [settingContext, setIsValueDirty],
  )

  const {isFetching} = useQuery<CopilotModelSetting>({
    queryKey: ['copilot-model-settings', 'settings', settingsPath],
    queryFn: async () => {
      const response = await verifiedFetchJSON(settingsPath)

      if (!response.ok) {
        throw new Error(`Failed to retrieve settings (${response.status} on ${response.url})`)
      }

      const persistedSetting: CopilotModelSetting = await response.json()
      wrappedInitialize(persistedSetting)

      return persistedSetting
    },
  })

  const updateSetting = useCallback(
    async (settingToUpdate?: CopilotModelSetting) => {
      const setting = settingToUpdate ?? settingContext.setting
      if (!setting) {
        setBanner({
          type: 'critical',
          title: 'Save failed',
          message: 'There was a problem saving your copilot model settings.',
        })
        return
      }
      setIsUpdating(true)
      clearBanner()
      try {
        const response = await verifiedFetchJSON(settingsPath, {
          method: 'POST',
          body: setting,
        })
        if (response.ok) {
          const persistedSetting = await response.json()
          wrappedInitialize(persistedSetting)
          setBanner({
            type: 'success',
            title: 'Save successful',
            message: 'Your copilot model settings have been successfully saved.',
          })
        } else {
          setBanner({
            type: 'critical',
            title: 'Save failed',
            message: 'There was a problem saving your copilot model settings.',
          })
        }
      } catch {
        setBanner({
          type: 'critical',
          title: 'Save failed',
          message: 'There was a problem saving your copilot model settings.',
        })
      } finally {
        setIsUpdating(false)
      }
    },
    [settingContext, settingsPath, clearBanner, setBanner, wrappedInitialize],
  )

  return useMemo(
    () => ({
      isSyncing: isFetching || isUpdating,
      updateSetting,
      ...settingContext,
      setValue: wrappedSetValue,
      initialize: wrappedInitialize,
    }),
    [isFetching, isUpdating, settingContext, updateSetting, wrappedSetValue, wrappedInitialize],
  )
}
