import {useCallback, useMemo} from 'react'
import {Button} from '@primer/react'
import {ModelsPanel} from '../components/panels/ModelsPanel'
import {RulesPanel} from '../components/panels/RulesPanel'
import {useSettings} from '../hooks/use-settings'
import type {ModelValue} from '../types'
import {usePermissions} from '../contexts/PermissionsContext'

export function OverviewPage() {
  const {setting, isSyncing, updateSetting, setValue} = useSettings()
  const {canWrite} = usePermissions()

  const selectedModels = useMemo(() => setting?.value ?? {}, [setting?.value])

  const setModel = useCallback(
    (key: string, value: ModelValue) => {
      setValue({
        ...selectedModels,
        [key]: value,
      })
    },
    [selectedModels, setValue],
  )

  return (
    <>
      <ModelsPanel selectedModels={selectedModels} setModel={setModel} showEnterpriseHeader showDisabledModels />
      <div className="d-flex flex-row flex-justify-start">
        <div className="d-flex gap-2">
          <Button disabled={!canWrite} loading={isSyncing} variant="primary" onClick={() => updateSetting(setting)}>
            Save
          </Button>
        </div>
      </div>
      <RulesPanel />
    </>
  )
}

try{ OverviewPage.displayName ||= 'OverviewPage' } catch {}