import type {SelectPanelItemInput} from '@primer/react'
import type {MultiSelectConditionExpression, Rule, Setting} from '@github-ui/ruleset-settings-state/types'

// see app/controllers/businesses/copilot_models_controller.rb#Publisher
export const Publisher = {
  OpenAI: 'openai',
  Gemini: 'gemini',
  Anthropic: 'anthropic',
  xAI: 'xai',
} as const
export type Publisher = (typeof Publisher)[keyof typeof Publisher]

// see app/controllers/businesses/copilot_models_controller.rb#Category
export const Category = {
  Fast: 'fast',
  Versatile: 'versatile',
  Powerful: 'powerful',
} as const
export type Category = (typeof Category)[keyof typeof Category]

export const ModelValue = {
  Unconfigured: 'unconfigured',
  Enabled: 'enabled',
  Disabled: 'disabled',
  NoPolicy: 'no_policy',
} as const
export type ModelValue = (typeof ModelValue)[keyof typeof ModelValue]

export type Model = {
  name: string
  displayName: string
  category?: Category
  publisher: Publisher
  isPreview: boolean
  value: ModelValue
}

export type AugmentedActionListItemInput = SelectPanelItemInput & Pick<Model, 'value'>

export type CopilotModelValue = Record<string, ModelValue>
export type CopilotModelSetting = Setting<CopilotModelValue, 'add', MultiSelectConditionExpression>
export type CopilotModelRule = Rule<CopilotModelValue, 'add', MultiSelectConditionExpression>

export type Paths = {
  modelsPath: string
  organizationsPath: string
  settingsPath: string
}

export const Page = {
  Overview: 'overview',
  CreateRule: 'createRule',
  UpdateRule: 'updateRule',
} as const
export type Page = (typeof Page)[keyof typeof Page]
export type PartialRouter = {
  page: Page
  ruleId?: number
  navigate(page: Page, ruleId?: number): void
}

export const BannerType = {
  Success: 'success',
  Critical: 'critical',
} as const
export type BannerType = (typeof BannerType)[keyof typeof BannerType]
export type Banner = {
  type: BannerType
  title: string
  message: string
}

export type EnabledFeatures = Record<string, boolean>
