import {Banner as PrimerBanner} from '@primer/react'
import {useBannerContext} from '../contexts/BannerContext'

export function Banner() {
  const {banner, clearBanner} = useBannerContext()

  if (!banner) {
    return null
  }

  return (
    <PrimerBanner
      hideTitle
      title={banner.message}
      variant={banner.type}
      onDismiss={clearBanner}
      aria-live="polite"
      aria-atomic="true"
    >
      <PrimerBanner.Description>{banner.message}</PrimerBanner.Description>
    </PrimerBanner>
  )
}

try{ Banner.displayName ||= 'Banner' } catch {}