import {type PropsWithChildren, createContext, useContext, useMemo} from 'react'
import type {Paths} from '../types'

export const PathsContext = createContext<Paths | undefined>(undefined)

export function PathsProvider({children, paths}: PropsWithChildren<{paths: Paths}>) {
  const value = useMemo(() => paths, [paths])
  return <PathsContext.Provider value={value}>{children}</PathsContext.Provider>
}

export function usePathsContext(): Paths {
  const context = useContext(PathsContext)
  if (!context) {
    throw new Error('usePathsContext must be used within a PathsProvider')
  }
  return context
}

try{ PathsContext.displayName ||= 'PathsContext' } catch {}
try{ PathsProvider.displayName ||= 'PathsProvider' } catch {}