import {useMemo} from 'react'
import {type Model, type CopilotModelValue, ModelValue} from '../types'
import {useQuery} from '@github-ui/react-query'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {usePathsContext} from '../contexts/PathsContext'

export function useModels(selectedModels?: CopilotModelValue) {
  const {modelsPath} = usePathsContext()
  const {data: models, isFetching} = useQuery({
    queryKey: ['copilot-model-settings', 'models', modelsPath],
    queryFn: async () => {
      const response = await verifiedFetchJSON(modelsPath)

      if (!response.ok) {
        throw new Error(`Failed to retrieve models (${response.status} on ${response.url})`)
      }

      return (await response.json()) as Model[]
    },
    placeholderData: [],
    staleTime: Infinity,
  })

  return useMemo(() => {
    const _models = models ?? [] // default value assignment in the render method breaks memoization
    const mappedModels: Model[] = selectedModels
      ? _models.map(model => ({
          ...model,
          value: selectedModels[model.name] || ModelValue.Unconfigured,
        }))
      : []
    const mappedSelectedModels: Model[] = mappedModels.filter(
      model => model.value === ModelValue.Enabled || model.value === ModelValue.NoPolicy,
    )
    const mappedSelectedAndUnconfiguredModels: Model[] = mappedModels.filter(
      model =>
        model.value === ModelValue.Enabled ||
        model.value === ModelValue.NoPolicy ||
        model.value === ModelValue.Unconfigured,
    )
    return {
      selectedModels: mappedSelectedModels,
      selectedAndUnconfiguredModels: mappedSelectedAndUnconfiguredModels,
      models: mappedModels,
      isSyncing: isFetching,
    }
  }, [selectedModels, models, isFetching])
}
